parameters.jsCode:
// ─────────────────────────────────────────────────────────────
// Data Simulator — generates 20 time-series readings per
// variable for a simulated CSTR (continuous stirred-tank reactor)
// ─────────────────────────────────────────────────────────────

const now = new Date();
const POINTS = 20;
const INTERVAL_MS = 5 * 60 * 1000;

const SPECS = {
  reactor_temp: {
    label: 'Reactor Temperature', unit: '°C',
    baseline: 82.0, noise: 1.2,
    min_valid: 65.0, max_valid: 105.0,
    alarm_low: 72.0, alarm_high: 95.0,
  },
  outlet_pressure: {
    label: 'Outlet Pressure', unit: 'bar',
    baseline: 3.10, noise: 0.06,
    min_valid: 1.5, max_valid: 6.0,
    alarm_low: 2.0, alarm_high: 4.5,
  },
  coolant_flow: {
    label: 'Coolant Flow Rate', unit: 'L/min',
    baseline: 95.0, noise: 3.5,
    min_valid: 20.0, max_valid: 200.0,
    alarm_low: 40.0, alarm_high: 160.0,
  },
  feed_pH: {
    label: 'Feed pH', unit: 'pH',
    baseline: 7.05, noise: 0.07,
    min_valid: 4.0, max_valid: 10.0,
    alarm_low: 6.2, alarm_high: 8.0,
  }
};

function randn() {
  let u = 0, v = 0;
  while (u === 0) u = Math.random();
  while (v === 0) v = Math.random();
  return Math.sqrt(-2.0 * Math.log(u)) * Math.cos(2.0 * Math.PI * v);
}

function round(val, dp) {
  return parseFloat(val.toFixed(dp));
}

const DECIMALS = {
  reactor_temp: 1,
  outlet_pressure: 3,
  coolant_flow: 1,
  feed_pH: 2
};

const ANOMALY_ROLL = Math.random();
const ANOMALY_TYPE =
  ANOMALY_ROLL < 0.30 ? 'none' :
  ANOMALY_ROLL < 0.55 ? 'spike' :
  ANOMALY_ROLL < 0.75 ? 'drift' :
  ANOMALY_ROLL < 0.88 ? 'dropout' :
  'range_violation';

const VAR_NAMES = Object.keys(SPECS);
const AFFECTED_VAR = VAR_NAMES[Math.floor(Math.random() * VAR_NAMES.length)];

const series = {};
for (const varName of VAR_NAMES) {
  series[varName] = [];
}

for (let i = 0; i < POINTS; i++) {
  const ts = new Date(now.getTime() - (POINTS - 1 - i) * INTERVAL_MS).toISOString();
  const isLast = i === POINTS - 1;

  for (const [varName, spec] of Object.entries(SPECS)) {
    const isAffected = varName === AFFECTED_VAR;
    let value;

    if (!isAffected || ANOMALY_TYPE === 'none') {
      value = spec.baseline + randn() * spec.noise;

    } else if (ANOMALY_TYPE === 'spike' && isLast) {
      const dir = Math.random() > 0.5 ? 1 : -1;
      value = spec.baseline + dir * spec.noise * (4 + Math.random() * 3);

    } else if (ANOMALY_TYPE === 'drift') {
      const driftStart = POINTS - 10;
      if (i >= driftStart) {
        const fraction = (i - driftStart) / (POINTS - driftStart);
        value = spec.baseline + randn() * spec.noise + fraction * spec.noise * 5;
      } else {
        value = spec.baseline + randn() * spec.noise;
      }

    } else if (ANOMALY_TYPE === 'dropout' && isLast) {
      const prev = series[varName][i - 1];
      value = prev ? prev.value : spec.baseline;

    } else if (ANOMALY_TYPE === 'range_violation' && isLast) {
      value = spec.max_valid * (1.05 + Math.random() * 0.10);

    } else {
      value = spec.baseline + randn() * spec.noise;
    }

    series[varName].push({
      timestamp: ts,
      value: round(value, DECIMALS[varName])
    });
  }
}

return [{
  json: {
    generated_at: now.toISOString(),
    anomaly_injected: ANOMALY_TYPE,
    affected_variable: ANOMALY_TYPE !== 'none' ? AFFECTED_VAR : null,
    specs: SPECS,
    series: series,
    latest_values: Object.fromEntries(
      VAR_NAMES.map(k => [k, series[k][series[k].length - 1].value])
    )
  }
}];

// ─────────────────────────────────────────────────────────────
// Anomaly Detector
// Reads series data from Data Simulator and runs 3 statistical
// tests per variable: Z-score, Rate-of-Change, Hard range check
// ─────────────────────────────────────────────────────────────

const { series, specs } = $input.first().json;

const Z_THRESHOLD     = 2.5;
const ROC_Z_THRESHOLD = 3.0;
const DROPOUT_TOL     = 1e-6;

const anomalies = [];

for (const [varName, spec] of Object.entries(specs)) {
  const points  = series[varName];
  const values  = points.map(p => p.value);
  const n       = values.length;
  const latest  = values[n - 1];
  const ts      = points[n - 1].timestamp;

  // ── Test 1: Rolling Z-score ───────────────────────────────
  // Use first 19 points as reference window.
  // This prevents the anomalous point from distorting the mean.
  const window  = values.slice(0, n - 1);
  const mean    = window.reduce((a, b) => a + b, 0) / window.length;
  const variance = window.reduce((s, v) => s + (v - mean) ** 2, 0) / window.length;
  const std     = Math.sqrt(variance);
  const zScore  = std > 0 ? Math.abs(latest - mean) / std : 0;

  // ── Test 2: Rate-of-Change Z-score ───────────────────────
  // Checks if the JUMP between the last two readings is unusual
  // compared to historical jumps in this variable.
  const deltas = [];
  for (let i = 1; i < n; i++) {
    deltas.push(Math.abs(values[i] - values[i - 1]));
  }
  const latestDelta  = deltas[deltas.length - 1];
  const histDeltas   = deltas.slice(0, deltas.length - 1);
  const deltaMean    = histDeltas.reduce((a, b) => a + b, 0) / histDeltas.length;
  const deltaVar     = histDeltas.reduce((s, d) => s + (d - deltaMean) ** 2, 0) / histDeltas.length;
  const deltaStd     = Math.sqrt(deltaVar);
  const rocZScore    = deltaStd > 0 ? (latestDelta - deltaMean) / deltaStd : 0;

  // ── Test 3: Hard range and alarm limit checks ─────────────
  const outOfRange   = latest < spec.min_valid || latest > spec.max_valid;
  const outOfAlarm   = latest < spec.alarm_low  || latest > spec.alarm_high;

  // ── Test 4: Sensor dropout (frozen reading) ───────────────
  const last3        = values.slice(-3);
  const isFrozen     = last3.length === 3 &&
                       Math.abs(last3[2] - last3[1]) < DROPOUT_TOL &&
                       Math.abs(last3[1] - last3[0]) < DROPOUT_TOL;

  // ── Decision: classify anomaly type and severity ──────────
  let anomalyType = null;
  let severity    = 'normal';

  if (outOfRange) {
    anomalyType = 'range_violation';
    severity    = 'critical';
  } else if (isFrozen) {
    anomalyType = 'sensor_dropout';
    severity    = 'high';
  } else if (zScore > Z_THRESHOLD && rocZScore > ROC_Z_THRESHOLD) {
    anomalyType = 'spike';
    severity    = 'high';
  } else if (zScore > Z_THRESHOLD) {
    anomalyType = 'statistical_deviation';
    severity    = 'medium';
  } else if (rocZScore > ROC_Z_THRESHOLD) {
    anomalyType = 'rapid_change';
    severity    = 'medium';
  } else if (outOfAlarm) {
    anomalyType = 'alarm_limit_breach';
    severity    = 'low';
  }

  if (anomalyType) {
    anomalies.push({
      variable:      varName,
      label:         spec.label,
      unit:          spec.unit,
      current_value: latest,
      baseline_mean: parseFloat(mean.toFixed(4)),
      baseline_std:  parseFloat(std.toFixed(4)),
      z_score:       parseFloat(zScore.toFixed(3)),
      roc_z_score:   parseFloat(rocZScore.toFixed(3)),
      anomaly_type:  anomalyType,
      severity:      severity,
      valid_range:   `${spec.min_valid}–${spec.max_valid} ${spec.unit}`,
      alarm_range:   `${spec.alarm_low}–${spec.alarm_high} ${spec.unit}`,
      timestamp:     ts,
      recent_trend:  values.slice(-5).map((v, i) =>
        `t-${(4 - i) * 5}min: ${v}`
      ).join(' | ')
    });
  }
}

// Sort by severity so the worst anomaly is always first
const SEV = { critical: 0, high: 1, medium: 2, low: 3 };
anomalies.sort((a, b) => SEV[a.severity] - SEV[b.severity]);

return [{
  json: {
    ...$input.first().json,
    has_anomaly:     anomalies.length > 0,
    anomaly_count:   anomalies.length,
    primary_anomaly: anomalies[0] ?? null,
    all_anomalies:   anomalies,
    checked_at:      new Date().toISOString()
  }
}];

// Build the QuickChart request body cleanly
// This avoids JSON expression issues in the HTTP Request node

const data = $input.first().json;
const varName = data.primary_anomaly.variable;
const varData = data.series[varName];

// Extract timestamps (show only HH:MM)
const labels = varData.map(p => p.timestamp.slice(11, 16));

// Extract values
const values = varData.map(p => p.value);

// Build the chart config as a proper JavaScript object
// then stringify it so HTTP Request receives clean JSON
const chartConfig = {
  width: 800,
  height: 400,
  backgroundColor: "white",
  chart: {
    type: "line",
    data: {
      labels: labels,
      datasets: [{
        label: `${data.primary_anomaly.label} (${data.primary_anomaly.unit})`,
        data: values,
        borderColor: "rgb(59,130,246)",
        backgroundColor: "rgba(59,130,246,0.08)",
        borderWidth: 2,
        pointRadius: 4,
        tension: 0.3,
        fill: true
      }]
    },
    options: {
      plugins: {
        title: {
          display: true,
          text: `ANOMALY DETECTED: ${data.primary_anomaly.label}`,
          color: "#dc2626",
          font: { size: 16, weight: "bold" }
        }
      },
      scales: {
        x: { ticks: { maxTicksLimit: 10 } },
        y: {
          title: {
            display: true,
            text: `${data.primary_anomaly.label} (${data.primary_anomaly.unit})`
          }
        }
      }
    }
  }
};

// Pass everything forward including the chart config as a string
return [{
  json: {
    ...data,
    chart_body: JSON.stringify(chartConfig)
  }
}];

